"""Regenerate Doorstop's canonical API declaration header from the SDK schema."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SCHEMA = Path(__file__).with_name("il2cpp-api-schema.json")
HEADER = ROOT / "src/Doorstop/src/windows/native_api_schema.h"


def generate_header() -> str:
    schema = json.loads(SCHEMA.read_text(encoding="utf-8"))
    lines = [
        "/* Generated by src/ApiResolver/generate_native_schema.py from the SDK schema.",
        " * Contains public declarations only; see il2cpp-api-schema.json for provenance.",
        " * Distributed under the GNU LGPL 2.1; see LICENSE.",
        " */",
        "#ifndef DOORSTOP_NATIVE_API_SCHEMA_H",
        "#define DOORSTOP_NATIVE_API_SCHEMA_H",
        "",
        "static const struct {",
        "    const char *canonical;",
        "    BOOL profiler_only;",
        "} native_api_schema[] = {",
    ]
    for entry in schema["functions"]:
        guard = entry["guard"]
        if guard not in (None, "IL2CPP_ENABLE_PROFILER"):
            raise ValueError(f"Unsupported compiler feature {guard}")
        name = entry["name"]
        if not name.startswith("il2cpp_") or not name.isascii() or not name.replace("_", "").isalnum():
            raise ValueError(f"Invalid public API declaration name {name}")
        lines.append(f'    {{"{name}", {"TRUE" if guard else "FALSE"}}},')
    lines.extend(["};", "", "#endif", ""])
    return "\n".join(lines)


if __name__ == "__main__":
    HEADER.write_text(generate_header(), encoding="ascii", newline="\n")
